// ---- Match is used for pattern matching ----

// ---- Simple enum ----
enum Coin {
    Penny,
    Nickel,
    Dime,
    Quarter,
    Dollar,
}

impl Coin {
    fn value_in_cents(&self) -> i32 {
        match self {
            Coin::Penny => 1,
            Coin::Nickel => 5,
            Coin::Dime => 10,
            Coin::Quarter => 25,
            Coin::Dollar => 100,
        }
    }
}

// ---- Enum with data ----
enum Action {
    Move { x: i32, y: i32 },
    Attack { target: String, damage: i32 },
    UseItem { name: String, quantity: i32 },
    Wait,
    Jump(i32),
}

impl Action {
    fn describe(&self) -> String {
        match self {
            Action::Move { x, y } => format!("Move to ({}, {})", x, y),
            Action::Attack { target, damage } => format!("Attack {} for {}", target, damage),
            Action::UseItem { name, quantity } => format!("Use {} (x{})", name, quantity),
            Action::Wait => String::from("Wait"),
            Action::Jump(height) => format!("Jump {} meters", height),
        }
    }
}

// ---- Matching with Option ----
fn get_value(opt: Option<i32>) -> i32 {
    match opt {
        Some(value) => value,
        None => 0,
    }
}

// ---- Matching with Result ----
fn handle_result(result: Result<i32, String>) -> String {
    match result {
        Ok(value) => format!("Success: {}", value),
        Err(e) => format!("Error: {}", e),
    }
}

// ---- Matching with ranges ----
fn check_score(score: i32) -> &'static str {
    match score {
        0 => "Zero",
        1..=10 => "Low",
        11..=50 => "Medium",
        51..=100 => "High",
        _ => "Extreme",
    }
}

// ---- Matching with guards ----
fn evaluate_number(n: i32) -> &'static str {
    match n {
        n if n < 0 => "Negative",
        0 => "Zero",
        n if n % 2 == 0 => "Even positive",
        _ => "Odd positive",
    }
}

// ---- Matching multiple patterns ----
fn is_vowel(c: char) -> bool {
    match c {
        'a' | 'e' | 'i' | 'o' | 'u' => true,
        _ => false,
    }
}

// ---- Matching on structs ----
struct Player {
    name: String,
    health: i32,
    level: i32,
}

fn check_player(player: Player) {
    match player {
        Player { name, health: 0, .. } => println!("{} is dead!", name),
        Player { name, health, level: 10.. } => println!("{} is a high-level player with {} HP", name, health),
        Player { name, health, level } => println!("{} is level {} with {} HP", name, level, health),
    }
}

fn main() {
    // ---- Matching coins ----
    let coin = Coin::Quarter;
    println!("Value: {} cents", coin.value_in_cents());

    // ---- Matching actions ----
    let actions = vec![
        Action::Move { x: 10, y: 20 },
        Action::Attack { target: String::from("Goblin"), damage: 15 },
        Action::UseItem { name: String::from("Potion"), quantity: 3 },
        Action::Wait,
        Action::Jump(5),
    ];

    for action in actions {
        println!("{}", action.describe());
    }

    // ---- Option ----
    println!("get_value(Some(42)): {}", get_value(Some(42)));
    println!("get_value(None): {}", get_value(None));

    // ---- Result ----
    println!("handle_result(Ok(42)): {}", handle_result(Ok(42)));
    println!("handle_result(Err(\"Error\".to_string())): {}", handle_result(Err("Error".to_string())));

    // ---- Ranges ----
    println!("check_score(0): {}", check_score(0));
    println!("check_score(5): {}", check_score(5));
    println!("check_score(30): {}", check_score(30));
    println!("check_score(75): {}", check_score(75));
    println!("check_score(200): {}", check_score(200));

    // ---- Guards ----
    println!("evaluate_number(-5): {}", evaluate_number(-5));
    println!("evaluate_number(0): {}", evaluate_number(0));
    println!("evaluate_number(6): {}", evaluate_number(6));
    println!("evaluate_number(7): {}", evaluate_number(7));

    // ---- Multiple patterns ----
    println!("is_vowel('a'): {}", is_vowel('a'));
    println!("is_vowel('b'): {}", is_vowel('b'));

    // ---- Struct matching ----
    let player1 = Player {
        name: String::from("Hero"),
        health: 0,
        level: 5,
    };

    let player2 = Player {
        name: String::from("Aragorn"),
        health: 100,
        level: 10,
    };

    let player3 = Player {
        name: String::from("Gandalf"),
        health: 80,
        level: 3,
    };

    check_player(player1);
    check_player(player2);
    check_player(player3);
}

